# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEKNOLOJİ BAĞLAMINDA AKSİYOLOJİK (ETİK VE DEĞER) PROBLEMLER</text>\n  <rect x="20" y="50" width="210" height="190" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">1. Güvenlik ve Mahremiyet</text>\n  <text x="30" y="98" font-size="10.5" fill="#334155">• Büyük veri (Big Data) ve</text>\n  <text x="38" y="114" font-size="10" fill="#475569">biyometrik veri takibi.</text>\n  <text x="30" y="136" font-size="10.5" font-weight="bold" fill="#991b1b">• Dijital Panoptikon:</text>\n  <text x="38" y="152" font-size="10" fill="#475569">Gönüllü gözetim ve kişisel</text>\n  <text x="38" y="166" font-size="10" fill="#475569">mahremiyetin aşınması.</text>\n  <text x="30" y="188" font-size="10.5" fill="#334155">• Deepfake, siber tehditler ve</text>\n  <text x="38" y="204" font-size="10" fill="#475569">otonom silah sistemleri.</text>\n\n  <rect x="245" y="50" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Değerlerin Tahribatı</text>\n  <text x="255" y="98" font-size="10.5" fill="#334155">• Araçsal aklın egemenliği ve</text>\n  <text x="263" y="114" font-size="10" fill="#475569">her şeyin metalaşması.</text>\n  <text x="255" y="136" font-size="10.5" font-weight="bold" fill="#b45309">• İlişkilerin Yüzeyselleşmesi:</text>\n  <text x="263" y="152" font-size="10" fill="#475569">Empati, sabır, dostluk ve</text>\n  <text x="263" y="166" font-size="10" fill="#475569">dayanışma değerlerinin</text>\n  <text x="263" y="180" font-size="10" fill="#475569">tüketim hızına kurban edilmesi.</text>\n  <text x="255" y="204" font-size="10.5" fill="#334155">• Ekolojik yıkım ve doğa istismarı.</text>\n\n  <rect x="470" y="50" width="210" height="190" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">3. Ahlaki Eylemin İmkânı</text>\n  <text x="480" y="98" font-size="10.5" fill="#334155">• Algoritmik manipülasyon ve</text>\n  <text x="488" y="114" font-size="10" fill="#475569">yankı odalarıyla iradenin</text>\n  <text x="488" y="128" font-size="10" fill="#475569">yönlendirilmesi.</text>\n  <text x="480" y="150" font-size="10.5" font-weight="bold" fill="#6d28d9">• Sorumluluk Boşluğu:</text>\n  <text x="488" y="166" font-size="10" fill="#475569">Otonom araç veya yapay zekâ</text>\n  <text x="488" y="180" font-size="10" fill="#475569">kararlarında ahlaki ve hukuki</text>\n  <text x="488" y="194" font-size="10" fill="#475569">failin (öznenin) kim olduğu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AHLAKİ EYLEMİN KOŞULLARI VE HANS JONAS\'IN SORUMLULUK İLKESİ</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Teknoloji Çağında Ahlaki Özne Sorunu</text>\n  <rect x="42" y="90" width="276" height="58" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="110" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">Klasik Etikte Ahlaki Eylem</text>\n  <text x="180" y="128" text-anchor="middle" font-size="10.5" fill="#334155">Bilinç + Özgür İrade + Seçim = Sorumluluk</text>\n  <text x="180" y="142" text-anchor="middle" font-size="10" fill="#475569">(İnsan eyleminin doğrudan failidir)</text>\n  <rect x="42" y="158" width="276" height="68" rx="6" fill="#ffffff" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="178" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b91c1c">Algoritmik Çağda Tehditler</text>\n  <text x="180" y="196" text-anchor="middle" font-size="10.5" fill="#334155">• İradenin algoritmalarla yönlendirilmesi</text>\n  <text x="180" y="212" text-anchor="middle" font-size="10.5" fill="#334155">• Otonom makinelerde sorumluluk boşluğu</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Hans Jonas: Sorumluluk Etiği</text>\n  <text x="380" y="102" font-size="10.5" fill="#14532d">• Modern teknoloji ve biyoteknoloji, doğayı ve</text>\n  <text x="388" y="118" font-size="10.5" fill="#14532d">insanlığın geleceğini değiştirme gücüne sahiptir.</text>\n  <text x="380" y="140" font-size="10.5" fill="#14532d">• Ahlaki sorumluluk yalnız bugünkü insanları</text>\n  <text x="388" y="156" font-size="10.5" fill="#14532d">değil, doğayı ve gelecek kuşakları da kapsar.</text>\n  <rect x="382" y="170" width="276" height="56" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Yeni Ahlaki Buyruk:</text>\n  <text x="520" y="204" text-anchor="middle" font-size="10" fill="#334155">\'Öyle eyle ki, eyleminin sonuçları yeryüzünde</text>\n  <text x="520" y="218" text-anchor="middle" font-size="10" fill="#334155">insan yaşamının sürekliliğiyle bağdaşsın!\'</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEKNOLOJİ FELSEFESİNDE ARGÜMAN YAPILANDIRMA MODELİ</text>\n  <rect x="25" y="50" width="650" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <rect x="45" y="68" width="190" height="154" rx="8" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="140" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Öncül (Etik İlke)</text>\n  <text x="55" y="118" font-size="10.5" fill="#334155">Bir eylemin ahlaki sorumluluk</text>\n  <text x="55" y="134" font-size="10.5" fill="#334155">doğurması için bilinçli ve</text>\n  <text x="55" y="150" font-size="10.5" fill="#334155">özgür iradeye sahip bir</text>\n  <text x="55" y="166" font-size="10.5" fill="#334155">özne tarafından seçilmesi</text>\n  <text x="55" y="182" font-size="10.5" fill="#334155">gerekir.</text>\n\n  <rect x="255" y="68" width="190" height="154" rx="8" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">2. Öncül (Olgu Tespiti)</text>\n  <text x="265" y="118" font-size="10.5" fill="#334155">Yapay zekâ algoritmaları</text>\n  <text x="265" y="134" font-size="10.5" fill="#334155">yüksek hesaplama gücüne</text>\n  <text x="265" y="150" font-size="10.5" fill="#334155">sahip olsa da öz bilinç,</text>\n  <text x="265" y="166" font-size="10.5" fill="#334155">vicdan ve özgür iradeye</text>\n  <text x="265" y="182" font-size="10.5" fill="#334155">sahip değildir.</text>\n\n  <rect x="465" y="68" width="190" height="154" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="560" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Sonuç (Felsefi Tez)</text>\n  <text x="475" y="118" font-size="10.5" font-weight="bold" fill="#166534">O hâlde; yapay zekâ</text>\n  <text x="475" y="134" font-size="10.5" fill="#14532d">sistemleri bağımsız birer</text>\n  <text x="475" y="150" font-size="10.5" fill="#14532d">ahlaki özne olamaz; etik</text>\n  <text x="475" y="166" font-size="10.5" fill="#14532d">ve hukuki sorumluluk</text>\n  <text x="475" y="182" font-size="10.5" fill="#14532d">onları tasarlayan ve</text>\n  <text x="475" y="198" font-size="10.5" fill="#14532d">kullanan insana aittir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
